text:
  & .owl-exchange-section {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding: 6px;

    background-color: var(--color-warning-soft);
    border: 1px solid var(--color-text-warning);
    color: var(--color-text-warning);
    font-size: 0.9rem;
    border-radius: 5px;

    & p {
      display: flex;
      gap: 6px;
      align-items: center;
      margin-block: 0;
    }

    & .install-addon-button {
      align-self: end;
    }
  }
}
